-- Migração: Limited Editions da Adrenalyn XL (187 cards, sem número oficial). Idempotente.
-- Rode depois de supabase_migration_collections_phase3.sql.
--
-- Fonte: data/adrenalyn-xl-limited.csv (lista de colecionadores — Collectosk). Códigos próprios:
-- AXLLE (Limited Edition, 90), AXLLH (Holo, 25), AXLPR (Premium, 12), AXLPG (Premium Gold, 6),
-- AXLXL (XXL, 36), AXLXH (XXL Holo, 18). Ficam fora do total de 630 da coleção.

alter table public.stickers drop constraint if exists stickers_block_type_check;
alter table public.stickers
  add constraint stickers_block_type_check
  check (block_type in ('TEAM','FWC','CC','LEG','SPECIAL','CONTENDER','LIMITED'));

on conflict (code) do update
  set album_id = excluded.album_id, block_id = excluded.block_id, block_name = excluded.block_name,
      block_type = excluded.block_type, group_key = excluded.group_key, position = excluded.position,
      number = excluded.number, name = excluded.name, team_code = excluded.team_code,
      card_type = excluded.card_type, player_position = excluded.player_position;
